import { getJson, postJson } from '../../api/http';

// A project as the API exposes it — it carries its client's NAME (the cross-entity join done on the
// server) so the list shows the client without a second lookup. The query key ['projects'] is the
// shared handle: the list reads it, the create form invalidates it.
export type Project = {
  id: number;
  name: string;
  clientId: number;
  clientName: string;
  archived: boolean;
};
export type NewProject = { name: string; clientId: number };

export const projectsKey = ['projects'] as const;

export const listProjects = (): Promise<Project[]> => getJson<Project[]>('/api/projects');

export const createProject = (body: NewProject): Promise<Project> =>
  postJson<Project>('/api/projects', body);

// Archive a project — tucks it away server-side (keeps the row, sets its archived flag) and returns
// the updated project. Callers invalidate ['projects'] on success so the list refetches and the row
// drops off, unless the archived ones are being shown.
export const archiveProject = (id: number): Promise<Project> =>
  postJson<Project>('/api/projects/archive', { id });

// The client options the form's select needs: shared with the clients feature by the ['clients']
// KEY (not an import), so adding a client refreshes this select too.
export type ClientOption = { id: number; name: string };
export const clientsKey = ['clients'] as const;
export const listClientOptions = (): Promise<ClientOption[]> =>
  getJson<ClientOption[]>('/api/clients');
===== src/main/frontend/slots/Slot.tsx =====
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: how features add UI without anything being edited ──────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region never lists what goes
// in it, so adding a panel, a table column, a row action, a toolbar control or a nav link is a NEW
// FILE and nothing existing is touched.
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts are the mechanism — do not edit them. ADD a
// file under slots/defs/ to declare a new region.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
===== src/main/frontend/api/http.ts =====
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

