        this.projectId = projectId;
        this.title = title;
        this.done = false;
    }

    public Long getId() {
        return id;
    }

    public Long getProjectId() {
        return projectId;
    }

    public String getTitle() {
        return title;
    }

    public boolean isDone() {
        return done;
    }

    /** Tick this task off (or back on) — the OPEN &lt;-&gt; DONE transition the toggle performs. */
    public void toggleDone() {
